public class DOMNodePointer_testNode_TriageGen0Test {

    private Node mockNode;
    private NodeTest mockTest;

    @Before
    public void setUp() {
        mockNode = mock(Node.class);
        mockTest = mock(NodeTest.class);
    }

    @Test
    public void testNullTestReturnsTrue() {
        assertTrue(DOMNodePointer.testNode(mockNode, null));
    }

    @Test
    public void testUnknownTestTypeReturnsFalse() {
        assertFalse(DOMNodePointer.testNode(mockNode, mockTest));
    }

    @Test
    public void testNodeNameTest_NonElementNodeReturnsFalse() {
        NodeNameTest nameTest = mock(NodeNameTest.class);
        when(mockNode.getNodeType()).thenReturn(Node.TEXT_NODE);
        assertFalse(DOMNodePointer.testNode(mockNode, nameTest));
    }

    @Test
    public void testNodeNameTest_WildcardWithNoPrefixReturnsTrue() {
        NodeNameTest nameTest = mock(NodeNameTest.class);
        when(nameTest.isWildcard()).thenReturn(true);
        when(nameTest.getNodeName()).thenReturn(new QName("any"));
        when(nameTest.getNamespaceURI()).thenReturn("uri");
        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);

        // Using MockedStatic to control DOMNodePointer static helper methods
        try (MockedStatic<DOMNodePointer> mockedStatic = mockStatic(DOMNodePointer.class)) {
            mockedStatic.when(() -> DOMNodePointer.getLocalName(any())).thenReturn("any");
            mockedStatic.when(() -> DOMNodePointer.getNamespaceURI(any())).thenReturn("uri");
            // We need to mock the internal equalStrings or ensure it works via the logic
            // Since equalStrings is likely private/package-private, we rely on the logic
            // In this case, wildcard && testPrefix == null logic:
            when(nameTest.getNodeName()).thenReturn(new QName(null, "any", null));

            assertTrue(DOMNodePointer.testNode(mockNode, nameTest));
        }
    }

    @Test
    public void testNodeNameTest_WildcardMatch() {
        NodeNameTest nameTest = mock(NodeNameTest.class);
        when(nameTest.isWildcard()).thenReturn(true);
        when(nameTest.getNodeName()).thenReturn(new QName("any"));
        when(nameTest.getNamespaceURI()).thenReturn("uri");
        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);

        try (MockedStatic<DOMNodePointer> mockedStatic = mockStatic(DOMNodePointer.class)) {
            mockedStatic.when(() -> DOMNodePointer.getLocalName(mockNode)).thenReturn("something");
            mockedStatic.when(() -> DOMNodePointer.getNamespaceURI(mockNode)).thenReturn("uri");
            // equalStrings is used. Assuming it's a standard string equality check.
            // We simulate the branch: wildcard || localName match
            assertTrue(DOMNodePointer.testNode(mockNode, nameTest));
        }
    }

    @Test
    public void testNodeNameTest_ExactMatch_NamespaceMatch() {
        NodeNameTest nameTest = mock(NodeNameTest.class);
        when(nameTest.isWildcard()).thenReturn(false);
        when(nameTest.getNodeName()).thenReturn(new QName("prefix", "local", "uri"));
        when(nameTest.getNamespaceURI()).thenReturn("uri");
        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);

        try (MockedStatic<DOMNodePointer> mockedStatic = mockStatic(DOMNodePointer.class)) {
            mockedStatic.when(() -> DOMNodePointer.getLocalName(mockNode)).thenReturn("local");
            mockedStatic.when(() -> DOMNodePointer.getNamespaceURI(mockNode)).thenReturn("uri");

            assertTrue(DOMNodePointer.testNode(mockNode, nameTest));
        }
    }

    @Test
    public void testNodeNameTest_ExactMatch_PrefixMatchWhenNSNull() {
        NodeNameTest nameTest = mock(NodeNameTest.class);
        when(nameTest.isWildcard()).thenReturn(false);
        when(nameTest.getNodeName()).thenReturn(new QName("p", "l", "uri"));
        when(nameTest.getNamespaceURI()).thenReturn("uri");
        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);

        try (MockedStatic<DOMNodePointer> mockedStatic = mockStatic(DOMNodePointer.class)) {
            mockedStatic.when(() -> DOMNodePointer.getLocalName(mockNode)).thenReturn("l");
            mockedStatic.when(() -> DOMNodePointer.getNamespaceURI(mockNode)).thenReturn(null);
            mockedStatic.when(() -> DOMNodePointer.getPrefix(mockNode)).thenReturn("p");

            assertTrue(DOMNodePointer.testNode(mockNode, nameTest));
        }
    }

    @Test
    public void testNodeNameTest_Mismatch() {
        NodeNameTest nameTest = mock(NodeNameTest.class);
        when(nameTest.isWildcard()).thenReturn(false);
        when(nameTest.getNodeName()).thenReturn(new QName("p", "wrong", "uri"));
        when(nameTest.getNamespaceURI()).thenReturn("uri");
        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);

        try (MockedStatic<DOMNodePointer> mockedStatic = mockStatic(DOMNodePointer.class)) {
            mockedStatic.when(() -> DOMNodePointer.getLocalName(mockNode)).thenReturn("local");
            assertFalse(DOMNodePointer.testNode(mockNode, nameTest));
        }
    }

    @Test
    public void testNodeTypeTest_AllCases() {
        NodeTypeTest typeTest = mock(NodeTypeTest.class);
        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);

        // NODE_TYPE_NODE
        when(typeTest.getNodeType()).thenReturn(Compiler.NODE_TYPE_NODE);
        assertTrue(DOMNodePointer.testNode(mockNode, typeTest)); // Element

        when(mockNode.getNodeType()).thenReturn(Node.DOCUMENT_NODE);
        assertTrue(DOMNodePointer.testNode(mockNode, typeTest)); // Document

        when(mockNode.getNodeType()).thenReturn(Node.TEXT_NODE);
        assertFalse(DOMNodePointer.testNode(mockNode, typeTest));

        // NODE_TYPE_TEXT
        when(typeTest.getNodeType()).thenReturn(Compiler.NODE_TYPE_TEXT);
        when(mockNode.getNodeType()).thenReturn(Node.TEXT_NODE);
        assertTrue(DOMNodePointer.testNode(mockNode, typeTest));

        when(mockNode.getNodeType()).thenReturn(Node.CDATA_SECTION_NODE);
        assertTrue(DOMNodePointer.testNode(mockNode, typeTest));

        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        assertFalse(DOMNodePointer.testNode(mockNode, typeTest));

        // NODE_TYPE_COMMENT
        when(typeTest.getNodeType()).thenReturn(Compiler.NODE_TYPE_COMMENT);
        when(mockNode.getNodeType()).thenReturn(Node.COMMENT_NODE);
        assertTrue(DOMNodePointer.testNode(mockNode, typeTest));

        when(mockNode.getNodeType()).thenReturn(Node.TEXT_NODE);
        assertFalse(DOMNodePointer.testNode(mockNode, typeTest));

        // NODE_TYPE_PI
        when(typeTest.getNodeType()).thenReturn(Compiler.NODE_TYPE_PI);
        when(mockNode.getNodeType()).thenReturn(Node.PROCESSING_INSTRUCTION_NODE);
        assertTrue(DOMNodePointer.testNode(mockNode, typeTest));

        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        assertFalse(DOMNodePointer.testNode(mockNode, typeTest));

        // Unknown NodeTypeTest value
        when(typeTest.getNodeType()).thenReturn(999);
        assertFalse(DOMNodePointer.testNode(mockNode, typeTest));
    }

    @Test
    public void testProcessingInstructionTest_Success() {
        ProcessingInstructionTest piTest = mock(ProcessingInstructionTest.class);
        ProcessingInstruction mockPI = mock(ProcessingInstruction.class);

        when(mockNode.getNodeType()).thenReturn(Node.PROCESSING_INSTRUCTION_NODE);
        when(piTest.getTarget()).thenReturn("target");
        when(mockPI.getTarget()).thenReturn("target");

        // Since the method casts node to ProcessingInstruction, we must provide a mock that is an instance of it
        // In a real test environment, one would use a concrete class or a spy
        // For this test, we assume Node is an interface and ProcessingInstruction extends it
        // We use a real object or a mock that passes the 'instanceof' check if possible.
        // However, the code says: (ProcessingInstruction) node.
        // Let's mock the behavior by using a spy or a subclass.

        class TestPI implements ProcessingInstruction {
            public String getTarget() { return "target"; }
            public int getNodeType() { return Node.PROCESSING_INSTRUCTION_NODE; }
            // Implement other required methods of ProcessingInstruction/Node...
        }

        TestPI piNode = new TestPI();
        assertTrue(DOMNodePointer.testNode(piNode, piTest));
    }

    @Test
    public void testProcessingInstructionTest_FailDifferentTarget() {
        ProcessingInstructionTest piTest = mock(ProcessingInstructionTest.class);

        class TestPI implements ProcessingInstruction {
            public String getTarget() { return "wrong"; }
            public int getNodeType() { return Node.PROCESSING_INSTRUCTION_NODE; }
        }

        TestPI piNode = new TestPI();
        when(piTest.getTarget()).thenReturn("target");
        assertFalse(DOMNodePointer.testNode(piNode, piTest));
    }

    @Test
    public void testProcessingInstructionTest_WrongNodeType() {
        ProcessingInstructionTest piTest = mock(ProcessingInstructionTest.class);
        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        assertFalse(DOMNodePointer.testNode(mockNode, piTest));
    }
}

// Minimal interfaces to allow compilation of the test if not in classpath
interface ProcessingInstruction extends Node {
    String getTarget();
}
